//go:build cgo

package astwalk

// cppRuntimeRule is deliberately local to the AST sidecar.
type cppRuntimeRule struct {
	kind, rule, cwe, severity, title, description string
}

// cppRuntimeRules mirrors the AST-detected cpp:* catalog entries.
var cppRuntimeRules = map[string]cppRuntimeRule{
	"raw-new-delete":                       {kind: "reliability", rule: "cpp:raw-new-delete", cwe: "CWE-401", severity: "medium", title: "Raw new and delete used", description: "Detects raw new and delete used instead of smart pointers."},
	"rule-of-three-violation":              {kind: "reliability", rule: "cpp:rule-of-three-violation", cwe: "CWE-401", severity: "high", title: "Rule of Three violation", description: "Detects destructor defined without copy operations."},
	"rule-of-five-violation":               {kind: "quality", rule: "cpp:rule-of-five-violation", cwe: "CWE-398", severity: "low", title: "Rule of Five violation", description: "Detects copy operations defined without move operations."},
	"owning-raw-pointer-member":            {kind: "quality", rule: "cpp:owning-raw-pointer-member", cwe: "CWE-401", severity: "medium", title: "Owning raw pointer member", description: "Detects class members declared as owning raw pointers."},
	"auto-ptr-deprecated":                  {kind: "quality", rule: "cpp:auto-ptr-deprecated", cwe: "CWE-676", severity: "medium", title: "Use of deprecated std::auto_ptr", description: "Detects usage of deprecated std::auto_ptr."},
	"unique-ptr-custom-deleter-mismatch":   {kind: "reliability", rule: "cpp:unique-ptr-custom-deleter-mismatch", cwe: "CWE-762", severity: "high", title: "std::unique_ptr array with scalar delete", description: "Detects scalar std::unique_ptr managing array allocations."},
	"shared-ptr-from-this-in-constructor":  {kind: "reliability", rule: "cpp:shared-ptr-from-this-in-constructor", cwe: "CWE-476", severity: "high", title: "shared_from_this in constructor", description: "Detects calling shared_from_this() inside constructor body."},
	"malloc-free-in-cpp":                   {kind: "quality", rule: "cpp:malloc-free-in-cpp", cwe: "CWE-762", severity: "medium", title: "C-style malloc or free used in C++", description: "Detects usage of C-style malloc or free instead of C++ new/delete or smart pointers."},
	"missing-virtual-destructor":           {kind: "reliability", rule: "cpp:missing-virtual-destructor", cwe: "CWE-401", severity: "high", title: "Polymorphic base missing virtual destructor", description: "Detects polymorphic base classes with non-virtual destructors."},
	"object-slicing-pass-by-value":         {kind: "reliability", rule: "cpp:object-slicing-pass-by-value", cwe: "CWE-843", severity: "medium", title: "Polymorphic object passed by value", description: "Detects polymorphic objects passed by value causing slicing."},
	"virtual-call-in-constructor":          {kind: "reliability", rule: "cpp:virtual-call-in-constructor", cwe: "CWE-670", severity: "medium", title: "Virtual call in constructor", description: "Detects virtual method calls inside constructor bodies."},
	"missing-override-specifier":           {kind: "quality", rule: "cpp:missing-override-specifier", cwe: "CWE-398", severity: "low", title: "Missing override specifier", description: "Detects overriding member functions missing the override specifier."},
	"hidden-virtual-function":              {kind: "reliability", rule: "cpp:hidden-virtual-function", cwe: "CWE-398", severity: "medium", title: "Derived method hides virtual base", description: "Detects derived class methods hiding overloaded virtual base methods."},
	"exception-in-destructor":              {kind: "reliability", rule: "cpp:exception-in-destructor", cwe: "CWE-248", severity: "high", title: "Exception escaping destructor", description: "Detects unhandled exceptions escaping destructors."},
	"catch-by-value":                       {kind: "quality", rule: "cpp:catch-by-value", cwe: "CWE-390", severity: "low", title: "Exception caught by value", description: "Detects catching exceptions by value causing object slicing."},
	"throw-raw-pointer":                    {kind: "reliability", rule: "cpp:throw-raw-pointer", cwe: "CWE-398", severity: "medium", title: "Throwing raw heap pointer", description: "Detects throwing raw heap pointers instead of exception objects."},
	"noexcept-function-throws":             {kind: "reliability", rule: "cpp:noexcept-function-throws", cwe: "CWE-248", severity: "high", title: "noexcept function throws exception", description: "Detects throw statements in functions declared noexcept."},
	"empty-catch-clause":                   {kind: "quality", rule: "cpp:empty-catch-clause", cwe: "CWE-390", severity: "low", title: "Empty catch block", description: "Detects empty catch blocks silently swallowing exceptions."},
	"rethrow-sliced-exception":             {kind: "reliability", rule: "cpp:rethrow-sliced-exception", cwe: "CWE-390", severity: "medium", title: "Rethrowing sliced exception by name", description: "Detects throw e instead of throw; in catch blocks."},
	"iterator-invalidation-loop":           {kind: "reliability", rule: "cpp:iterator-invalidation-loop", cwe: "CWE-416", severity: "high", title: "Container modified during iteration", description: "Detects container modifications invalidating iterators during loop."},
	"dangling-string-view-temporary":       {kind: "reliability", rule: "cpp:dangling-string-view-temporary", cwe: "CWE-825", severity: "high", title: "string_view bound to temporary", description: "Detects std::string_view bound to temporary std::string."},
	"std-move-on-const-object":             {kind: "quality", rule: "cpp:std-move-on-const-object", cwe: "CWE-398", severity: "low", title: "std::move called on const object", description: "Detects std::move on const objects inhibiting move semantics."},
	"container-access-empty":               {kind: "reliability", rule: "cpp:container-access-empty", cwe: "CWE-125", severity: "high", title: "front/back on potentially empty container", description: "Detects front() or back() called without empty check."},
	"iterator-past-the-end-deref":          {kind: "reliability", rule: "cpp:iterator-past-the-end-deref", cwe: "CWE-125", severity: "high", title: "Dereferencing past-the-end iterator", description: "Detects dereferencing container end() iterators."},
	"map-operator-bracket-unwanted-insert": {kind: "quality", rule: "cpp:map-operator-bracket-unwanted-insert", cwe: "CWE-400", severity: "low", title: "operator[] lookup on std::map", description: "Detects operator[] used for lookup inserting default elements."},
	"algorithm-pass-by-value-functor":      {kind: "reliability", rule: "cpp:algorithm-pass-by-value-functor", cwe: "CWE-398", severity: "medium", title: "Stateful functor passed by value", description: "Detects stateful functors passed by value to STL algorithms."},
	"unnecessary-temporary-vector":         {kind: "quality", rule: "cpp:unnecessary-temporary-vector", cwe: "CWE-400", severity: "low", title: "Temporary vector allocated", description: "Detects temporary vector allocated instead of using span."},
	"dangling-reference-span":              {kind: "reliability", rule: "cpp:dangling-reference-span", cwe: "CWE-825", severity: "high", title: "std::span references temporary", description: "Detects std::span referencing temporary container."},
	"find-on-associative-container":        {kind: "quality", rule: "cpp:find-on-associative-container", cwe: "CWE-400", severity: "low", title: "std::find on associative container", description: "Detects std::find algorithm used instead of member find()."},
	"manual-mutex-lock-unlock":             {kind: "reliability", rule: "cpp:manual-mutex-lock-unlock", cwe: "CWE-667", severity: "high", title: "Manual mutex lock/unlock", description: "Detects manual mutex lock/unlock instead of lock_guard."},
	"condition-variable-spurious-wakeup":   {kind: "reliability", rule: "cpp:condition-variable-spurious-wakeup", cwe: "CWE-835", severity: "medium", title: "condition_variable wait without predicate", description: "Detects condition_variable wait without predicate loop."},
	"lock-inversion-deadlock":              {kind: "reliability", rule: "cpp:lock-inversion-deadlock", cwe: "CWE-833", severity: "high", title: "Multiple locks without scoped_lock", description: "Detects multiple mutexes acquired without std::scoped_lock."},
	"shared-variable-no-synchronization":   {kind: "reliability", rule: "cpp:shared-variable-no-synchronization", cwe: "CWE-362", severity: "high", title: "Shared variable without synchronization", description: "Detects shared variable accessed in threads without synchronization."},
	"thread-joinable-destructor":           {kind: "reliability", rule: "cpp:thread-joinable-destructor", cwe: "CWE-404", severity: "high", title: "std::thread destroyed while joinable", description: "Detects joinable std::thread destroyed without join/detach."},
	"async-future-discarded":               {kind: "reliability", rule: "cpp:async-future-discarded", cwe: "CWE-400", severity: "medium", title: "std::async return value discarded", description: "Detects discarded std::async future causing synchronous block."},
	"double-checked-locking-pattern":       {kind: "reliability", rule: "cpp:double-checked-locking-pattern", cwe: "CWE-362", severity: "medium", title: "Double-checked locking without call_once", description: "Detects double-checked locking without std::call_once."},
	"c-style-cast-in-cpp":                  {kind: "quality", rule: "cpp:c-style-cast-in-cpp", cwe: "CWE-704", severity: "low", title: "C-style cast in C++ code", description: "Detects C-style casts instead of named C++ cast operators."},
	"reinterpret-cast-pointer-to-int":      {kind: "reliability", rule: "cpp:reinterpret-cast-pointer-to-int", cwe: "CWE-704", severity: "high", title: "reinterpret_cast pointer to narrow int", description: "Detects reinterpret_cast from pointer to narrower integer."},
	"const-cast-removing-constness":        {kind: "reliability", rule: "cpp:const-cast-removing-constness", cwe: "CWE-704", severity: "high", title: "const_cast modifying const object", description: "Detects const_cast used to mutate immutable objects."},
	"reinterpret-cast-unrelated-classes":   {kind: "reliability", rule: "cpp:reinterpret-cast-unrelated-classes", cwe: "CWE-843", severity: "high", title: "reinterpret_cast between unrelated classes", description: "Detects reinterpret_cast between unrelated class types."},
	"type-punning-union-misuse":            {kind: "reliability", rule: "cpp:type-punning-union-misuse", cwe: "CWE-843", severity: "medium", title: "Union used for type punning", description: "Detects union used for type punning in C++."},
	"null-macro-instead-of-nullptr":        {kind: "quality", rule: "cpp:null-macro-instead-of-nullptr", cwe: "CWE-476", severity: "low", title: "NULL instead of nullptr", description: "Detects NULL or 0 used for null pointer constants."},
	"typedef-instead-of-using":             {kind: "quality", rule: "cpp:typedef-instead-of-using", cwe: "CWE-398", severity: "low", title: "typedef instead of using", description: "Detects typedef used instead of using type alias."},
	"raw-loop-instead-of-range-for":        {kind: "quality", rule: "cpp:raw-loop-instead-of-range-for", cwe: "CWE-398", severity: "low", title: "Index loop instead of range-for", description: "Detects index loop over container instead of range-for."},
	"missing-constexpr-specifier":          {kind: "quality", rule: "cpp:missing-constexpr-specifier", cwe: "CWE-398", severity: "low", title: "Compile-time constant missing constexpr", description: "Detects compile-time constants declared without constexpr."},
	"c-style-variadic-function":            {kind: "quality", rule: "cpp:c-style-variadic-function", cwe: "CWE-398", severity: "low", title: "C-style variadic function used in C++", description: "Detects C-style variadic functions (...) instead of variadic templates."},
	"bind-instead-of-lambda":               {kind: "quality", rule: "cpp:bind-instead-of-lambda", cwe: "CWE-398", severity: "low", title: "std::bind instead of lambda", description: "Detects std::bind used instead of C++ lambda expressions."},
	"explicit-constructor-missing":         {kind: "quality", rule: "cpp:explicit-constructor-missing", cwe: "CWE-398", severity: "low", title: "Single-argument constructor not explicit", description: "Detects single-argument constructors missing explicit."},
	"default-delete-special-members":       {kind: "quality", rule: "cpp:default-delete-special-members", cwe: "CWE-398", severity: "low", title: "Empty constructor instead of = default", description: "Detects empty constructor body instead of = default."},
	"enum-unscoped-in-header":              {kind: "quality", rule: "cpp:enum-unscoped-in-header", cwe: "CWE-398", severity: "low", title: "Unscoped enum in header", description: "Detects unscoped enum declarations in header files."},
	"unbounded-template-recursion":         {kind: "reliability", rule: "cpp:unbounded-template-recursion", cwe: "CWE-835", severity: "high", title: "Template recursion without base case", description: "Detects template recursion without termination base case."},
	"missing-typename-dependent-type":      {kind: "quality", rule: "cpp:missing-typename-dependent-type", cwe: "CWE-398", severity: "low", title: "Dependent type missing typename", description: "Detects dependent type names missing typename keyword."},
	"export-template-obsolete":             {kind: "quality", rule: "cpp:export-template-obsolete", cwe: "CWE-676", severity: "info", title: "Obsolete export template keyword", description: "Detects obsolete export template keyword usage."},
	"sql-query-concatenation":              {kind: "sast", rule: "cpp:sql-query-concatenation", cwe: "CWE-89", severity: "high", title: "SQL query string concatenation", description: "Detects SQL query built with std::string concatenation."},
	"system-command-execution":             {kind: "sast", rule: "cpp:system-command-execution", cwe: "CWE-78", severity: "high", title: "system() command execution", description: "Detects executing system() with concatenated strings."},
	"path-traversal-filesystem":            {kind: "sast", rule: "cpp:path-traversal-filesystem", cwe: "CWE-22", severity: "high", title: "Path constructed without canonical check", description: "Detects std::filesystem::path constructed from untrusted input without canonical check."},
	"xml-external-entity-parser":           {kind: "sast", rule: "cpp:xml-external-entity-parser", cwe: "CWE-611", severity: "high", title: "XML parser external entity enabled", description: "Detects XML parser without external entity protection."},
	"untrusted-deserialization-boost":      {kind: "sast", rule: "cpp:untrusted-deserialization-boost", cwe: "CWE-502", severity: "high", title: "boost::serialization untrusted stream", description: "Detects boost::serialization reading untrusted input streams."},
	"format-string-user-input":             {kind: "sast", rule: "cpp:format-string-user-input", cwe: "CWE-134", severity: "high", title: "std::format with dynamic format string", description: "Detects std::format called with dynamic format strings."},
	"ldap-query-concatenation":             {kind: "sast", rule: "cpp:ldap-query-concatenation", cwe: "CWE-90", severity: "high", title: "LDAP filter string concatenation", description: "Detects LDAP queries constructed with string concatenation."},
	"regex-dos-dynamic-pattern":            {kind: "sast", rule: "cpp:regex-dos-dynamic-pattern", cwe: "CWE-1333", severity: "medium", title: "std::regex with dynamic pattern", description: "Detects dynamic std::regex pattern compilation."},
}
